DROP TABLE IF EXISTS `contractor_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `contractor_assignments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(10) unsigned NOT NULL,
  `contractor_partner_id` int(10) unsigned NOT NULL COMMENT 'partners.id where kyc_type=Contractor',
  `contractor_user_id` int(10) unsigned DEFAULT NULL COMMENT 'Specific contractor user assigned',
  `contractor_team_id` int(11) DEFAULT NULL,
  `contractor_team_name` varchar(150) DEFAULT NULL,
  `assigned_by` int(10) unsigned NOT NULL COMMENT 'Project Manager user id',
  `assigned_at` datetime DEFAULT current_timestamp(),
  `target_date` date DEFAULT NULL,
  `work_order_notes` text DEFAULT NULL,
  `pickup_location` varchar(255) DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `status` varchar(100) NOT NULL DEFAULT 'Assigned',
  `accepted_by` int(10) unsigned DEFAULT NULL,
  `accepted_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `completion_remarks` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contractor_user_id` (`contractor_user_id`),
  KEY `assigned_by` (`assigned_by`),
  KEY `accepted_by` (`accepted_by`),
  KEY `idx_order` (`order_id`),
  KEY `idx_contractor` (`contractor_partner_id`),
  KEY `idx_status` (`status`),
  CONSTRAINT `contractor_assignments_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `contractor_assignments_ibfk_2` FOREIGN KEY (`contractor_partner_id`) REFERENCES `partners` (`id`),
  CONSTRAINT `contractor_assignments_ibfk_3` FOREIGN KEY (`contractor_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `contractor_assignments_ibfk_4` FOREIGN KEY (`assigned_by`) REFERENCES `users` (`id`),
  CONSTRAINT `contractor_assignments_ibfk_5` FOREIGN KEY (`accepted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

