  `is_blocker` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'If 1, this update is a blocker — SLA pauses',
  `is_resumed` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'If 1, installation resumed — SLA resumes',
  `delay_reason` enum('Customer Unavailable','Access Denied','Weather','Missing Materials','Technical Issue','Other') DEFAULT NULL,
  `notes` text NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_assignment` (`assignment_id`),
  KEY `idx_order` (`order_id`),
  CONSTRAINT `contractor_progress_updates_ibfk_1` FOREIGN KEY (`assignment_id`) REFERENCES `contractor_assignments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `contractor_progress_updates_ibfk_2` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `contractor_progress_updates_ibfk_3` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
