--
-- Table structure for table `partners`
--

DROP TABLE IF EXISTS `partners`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `partners` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `trading_name` varchar(200) DEFAULT NULL,
  `partner_type` enum('ISP','Reseller','VAR','Enterprise','Government','Contractor','Other') NOT NULL DEFAULT 'Other',
  `partner_category` varchar(50) NOT NULL DEFAULT 'Partner',
  `kyc_type` enum('Partner','Contractor') NOT NULL DEFAULT 'Partner',
  `customer_category` varchar(100) DEFAULT NULL,
  `industry_sector` varchar(100) DEFAULT NULL,
  `nature_of_business` text DEFAULT NULL,
  `registration_number` varchar(100) DEFAULT NULL,
  `tin` varchar(100) DEFAULT NULL,
  `vat_vrn` varchar(100) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `contact_person_name` varchar(200) DEFAULT NULL,
  `contact_phone` varchar(50) DEFAULT NULL,
  `contact_email` varchar(200) DEFAULT NULL,
  `city_region` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT 'Tanzania',
  `kam_id` int(10) unsigned DEFAULT NULL,
  `assigned_kam_name` varchar(100) DEFAULT NULL,
  `status` enum('Active','Inactive','Suspended') NOT NULL DEFAULT 'Active',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_kyc_type` (`kyc_type`),
  KEY `idx_kam` (`kam_id`)
) ENGINE=InnoDB AUTO_INCREMENT=91 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

